  Lemma sc_B2_cases : forall (s5' : as_St H) (LB1 LB2 LB NEW4 : list block) (m5 : mem) (N : Z) (p5 : bptr) (A : Z) (p3 : bptr) (stb : Z),
      as_RHEAP H s5' LB2 m5 -> 0 <= N ->
      (N = 0 -> LB2 = LB1) -> (1 <= N -> LB2 = (p5, A, N) :: LB1) ->
      (1 <= N -> rblock_range A N /\ addressable m5 A N /\ exists junk, rw_cells asegs m5 A [CB (Z.to_nat N) junk]) -> (N = 0 -> A = 0) ->
      LB1 = NEW4 ++ LB -> In (p3, stb, SZ_SPCI_STATE) NEW4 ->
      exists (NEW : list block) (junk : list byte),
        LB2 = NEW ++ LB /\ st_LB N p5 A LB1 = LB2 /\ (forall b, In b LB1 -> In b LB2) /\ In (p3, stb, SZ_SPCI_STATE) NEW
        /\ (1 <= N -> rw_cells asegs m5 A [CB (Z.to_nat N) junk])
        /\ ((N = 0 /\ A = 0)
            \/ (1 <= N /\ In (p5, A, N) NEW /\ In (p5, A, N) LB2 /\ (forall b, In b LB1 -> blk_id b <> p5)
                /\ rblock_range A N /\ addressable m5 A N /\ 0 <= A /\ AIMG_TOP <= A /\ A + N <= aceil /\ A + N <= AAPP_HI /\ aapp A N /\ A mod 8 = 0)).
  Proof.
    intros s5' LB1 LB2 LB NEW4 m5 N p5 A p3 stb HEAP NR LBZ LBP BLKA AZ E4 IN3.
    destruct (Z.eq_dec N 0) as [N0|NZ].
    - exists NEW4, []. rewrite (LBZ N0). unfold st_LB. rewrite (proj2 (Z.eqb_eq N 0) N0).
      split; [exact E4|]. split; [reflexivity|]. split; [intros b Hb; exact Hb|]. split; [exact IN3|].
      split; [intros K; exfalso; clear - K N0; lia|]. left. split; [exact N0| exact (AZ N0)].
    - assert (N1 : 1 <= N) by (clear - NR NZ; lia). pose proof (LBP N1) as E. destruct (BLKA N1) as (RB & AD & junk & CJ).
      exists ((p5, A, N) :: NEW4), junk. unfold st_LB. destruct (Z.eqb_spec N 0); [exfalso; clear - N1 e; lia|].
      split; [rewrite E, E4; reflexivity|]. split; [rewrite E; reflexivity|]. split; [intros b Hb; rewrite E; right; exact Hb|].
      split; [right; exact IN3|]. split; [intros _; exact CJ|]. right.
      pose proof (rblock_bounds _ _ RB) as (B0 & _ & B2 & B3 & B4 & B5). pose proof RB as (_ & _ & _ & AP & _).
      pose proof (ah_nodup H HH _ _ _ HEAP) as ND. rewrite E in ND. cbn [map blk_id fst snd] in ND. apply List.NoDup_cons_iff in ND. destruct ND as [NI _].
      split; [exact N1|]. split; [left; reflexivity|]. split; [rewrite E; left; reflexivity|].
      split; [intros b Hb Eb; apply NI; rewrite <- Eb; apply in_map; exact Hb|].
      split; [exact RB|]. split; [exact AD|]. split; [exact B0|]. split; [exact B3|]. split; [exact B4|]. split; [exact B2|]. split; [exact AP| exact B5].
  Qed.
